def title_to_purpose(title):
    return f"{title}을 배치해 방문자가 필요한 행동을 빠르게 이해하고 실행하도록 돕습니다."

def make_item(seq, family_id, family, location, title, idx):
    example = f"{location}에서 {title}을 사용해 정보 탐색과 다음 행동을 한 화면 안에서 연결합니다."
    pattern = ["명확한 우선순위와 한 가지 핵심 행동", "상태·오류·완료 피드백을 함께 제공", "키보드·모바일·스크린리더까지 고려"][idx % 3]
    return {"id": seq, "category": family, "location": location, "name": title, "purpose": title_to_purpose(title), "pattern": pattern, "example": example, "tools": tools_by_family[family]}

items = []
seq = 1
for family_id, family, location, titles in families:
    for idx, title in enumerate(titles):
        items.append(make_item(seq, family_id, family, location, title, idx))
        seq += 1
assert len(items) == 350

out = Path('/home/ubuntu/ai-tools-directory/client/src/lib/uiCatalog350.ts')
out.write_text('''// 350개 홈페이지 UI 위치·기능 카탈로그. 패턴 참고용이며 프로젝트에 맞게 조정합니다.\nexport type UiCatalogEntry = { id: number; category: string; location: string; name: string; purpose: string; pattern: string; example: string; tools: string };\nexport const uiCatalog350: UiCatalogEntry[] = ''' + json.dumps(items, ensure_ascii=False, indent=2) + ';\n')
print(f'generated {len(items)} entries at {out}')
